/**
 * TTOken Code distribution layer, embedded so Desktop packaging ships it without an extra resource.
 * Generated by ttoken/apply-brand.mjs from ttoken/layer/cordis.patch.yml; edit that file instead.
 */

import { mkdirSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

const LAYER = "# Lapisan distribusi TTOken Code.\n#\n# Diterapkan paling akhir oleh Host desktop, di atas bundle base dan web-app.\n# Formatnya sama dengan overlay `--patch` upstream: baris ber-`id` mengganti\n# seluruh `config` baris yang dituju, jadi setiap baris di bawah menulis ulang\n# semua field yang ia miliki.\n#\n# Sumber kebenaran ada di file ini. `ttoken/apply-brand.mjs` menanamkannya ke\n# `apps/desktop-host/src/ttoken-layer.ts`; jangan edit file hasil itu.\n\n# Model bawaan untuk Agent baru: rute Gateway, bukan rute resmi DeepSeek.\n- id: agent-default-model\n  config:\n    provider: ttoken\n    model: deepseek/deepseek-v4.1-flash\n\n# TTOken Gateway sebagai rute OpenAI-compatible. Key tidak ditulis di sini:\n# `apiKeyEnv` adalah referensi kredensial yang diisi user lewat halaman Models.\n# Daftar model mengikuti lineup Gateway (FENRIR_MODEL_SLUGS di repo TTOken).\n- id: llm-pi-ai\n  config:\n    providers:\n      ttoken:\n        displayName: TTOken Gateway\n        apiKeyEnv: TTOKEN_API_KEY\n        api: openai-completions\n        baseURL: https://api.ttoken.dev/v1\n        models:\n          - id: deepseek/deepseek-v4.1-flash\n            name: DeepSeek V4.1 Flash\n            contextWindow: 1000000\n            maxTokens: 128000\n          - id: z-ai/glm-5.3-flash\n            name: GLM 5.3 Flash\n            contextWindow: 1000000\n            maxTokens: 128000\n          - id: qwen/qwen3.8-27b\n            name: Qwen 3.8 27B\n            contextWindow: 256000\n            maxTokens: 64000\n\n# Analitik produk upstream menyala secara bawaan di profil desktop dan\n# mengirim ke kolektor DeepSeek. Distribusi ini mematikan analitik dan\n# exporter-nya. Pemanggil analitik di klien semuanya opsional.\n- id: product-analytics\n  disabled: true\n- id: desktop-product-telemetry\n  disabled: true\n\n# Unggahan log sesi saat user memberi feedback juga menuju kolektor DeepSeek.\n# Ini setara dengan saklar DSH_TELEMETRY_DISABLED milik upstream.\n- id: session-telemetry-otel\n  disabled: true\n\n# Plugin yang hanya berguna dengan layanan DeepSeek, atau mengirim data ke\n# sana: provider resmi DeepSeek dan pendukungnya, unggahan log sesi untuk\n# melatih model DeepSeek, pencarian native DeepSeek, impor riwayat chat dari\n# situs DeepSeek, berbagi sesi lewat server terpisah, dan skill lencana DSH.\n# Halaman Plugins tidak mendaftar paket ini (HIDDEN_PACKAGES di apply-brand.mjs).\n- id: llm-deepseek\n  disabled: true\n- id: deepseek-llm-api-extensions\n  disabled: true\n- id: plugin-package-inventory-deepseek\n  disabled: true\n- id: session-log-deepseek\n  disabled: true\n- id: ui-settings-session-log\n  disabled: true\n- id: web-search-deepseek\n  disabled: true\n- id: deepseek-chat-import\n  disabled: true\n- id: liveshare-share-host\n  disabled: true\n- id: skill-badge\n  disabled: true\n\n# Mati sampai diarahkan ke server TTOken: login akun dan notifikasinya,\n# pencarian dan pengambilan halaman web, serta analitik. Alamat bawaannya\n# adalah server DeepSeek.\n- id: deepseek-account\n  disabled: true\n- id: deepseek-auth\n  disabled: true\n- id: llm-deepseek-account\n  disabled: true\n- id: ui-settings-account\n  disabled: true\n- id: ui-account-notifications\n  disabled: true\n- id: web-deepseek-api\n  disabled: true\n- id: ui-settings-web-search\n  disabled: true\n"

/**
 * Write the distribution layer into the Desktop profile directory.
 * @param profileDirectory - Desktop profile directory that Electron passes to the Host.
 * @returns Absolute overlay path for the profile launcher's patch list.
 */
export function materializeTtokenLayer(profileDirectory: string): string {
  mkdirSync(profileDirectory, { recursive: true })
  const path = join(profileDirectory, 'ttoken.cordis.patch.yml')
  writeFileSync(path, LAYER, 'utf8')
  return path
}
